import { isGenerateName, parseGenerateSpec } from "./generated-secrets.js";
import { ENV_NAME_PATTERN, validateSecretConfigFileEntry } from "./service-manifest-shared.js";
/** `secrets` must be { required?: string[], optional?: string[], generate?: object, files?: array }: the generator fails on anything else. */
export function secretsErrors(manifest, displayPath) {
    const secrets = manifest.secrets;
    if (secrets === undefined || secrets === null)
        return [];
    if (typeof secrets !== "object" || Array.isArray(secrets))
        return [`${displayPath}.secrets: expected an object like { "required": ["NAME"] }`];
    const errors = [];
    for (const kind of ["required", "optional"]) {
        const names = secrets[kind];
        if (names === undefined)
            continue;
        if (!Array.isArray(names)) {
            errors.push(`${displayPath}.secrets.${kind}: expected a list of environment variable names`);
            continue;
        }
        for (const name of names) {
            if (typeof name !== "string" || !ENV_NAME_PATTERN.test(name))
                errors.push(`${displayPath}.secrets.${kind}: ${JSON.stringify(name)} is not an environment variable name (letters, digits and underscores, not starting with a digit)`);
        }
    }
    const files = secrets.files;
    if (files !== undefined && files !== null) {
        if (manifest.appType !== "bring-your-own") {
            errors.push(`${displayPath}.secrets.files: only applies to bring-your-own resources (appType "bring-your-own")`);
        }
        else if (!Array.isArray(files)) {
            errors.push(`${displayPath}.secrets.files: expected an array of { name, source, target }`);
        }
        else {
            for (let i = 0; i < files.length; i++) {
                const field = `${displayPath}.secrets.files[${i}]`;
                errors.push(...validateSecretConfigFileEntry(files[i], field, "secret"));
            }
        }
    }
    errors.push(...generateSecretErrors(manifest, secrets, displayPath));
    return errors;
}
/** `secrets.generate` (#3140): valid specs, valid names, and no fixed value in `env`/`params` for a generated name. */
function generateSecretErrors(manifest, secrets, displayPath) {
    const generate = secrets.generate;
    if (generate === undefined)
        return [];
    if (!generate || typeof generate !== "object" || Array.isArray(generate))
        return [`${displayPath}.secrets.generate: expected an object like { "NAME": "hex:32" }`];
    const errors = [];
    for (const [name, spec] of Object.entries(generate)) {
        if (!isGenerateName(name))
            errors.push(`${displayPath}.secrets.generate: ${JSON.stringify(name)} is not an environment variable name (letters, digits and underscores, not starting with a digit)`);
        const parsed = parseGenerateSpec(spec);
        if (typeof parsed === "string")
            errors.push(`${displayPath}.secrets.generate.${name}: ${parsed}`);
        for (const field of ["env", "params"]) {
            const values = manifest[field];
            if (values && typeof values === "object" && !Array.isArray(values) && name in values)
                errors.push(`${displayPath}.${field}.${name}: also generated by secrets.generate, so this fixed value would replace the generated one; remove one of them`);
        }
    }
    return errors;
}
export function secretConflictWarnings(manifest, displayPath) {
    const secrets = manifest.secrets;
    if (!secrets || typeof secrets !== "object")
        return [];
    const declared = new Set();
    for (const kind of ["required", "optional"]) {
        const names = secrets[kind];
        if (Array.isArray(names))
            for (const name of names)
                if (typeof name === "string")
                    declared.add(name);
    }
    const warnings = [];
    for (const field of ["params", "env"]) {
        const values = manifest[field];
        if (!values || typeof values !== "object" || Array.isArray(values))
            continue;
        for (const name of Object.keys(values)) {
            if (declared.has(name))
                warnings.push(`${displayPath}.${field}.${name}: also listed in secrets, so this literal value is used and the secret from .env is ignored; remove one of them`);
        }
    }
    return warnings;
}
